insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'visuospatial-rotation'), 'overall', 0, 30, 'Developing', 'Distinguishing a true rotation from a mirrored look-alike is difficult right now — a very common starting point, since mirror-image confusion is exactly what this paradigm is designed to probe.', ARRAY[convert_from(decode('VHJhY2Ugb25lIGRpc3RpbmN0aXZlIGZlYXR1cmUgKGEgbm90Y2ggb3IgY29ybmVyKSBvbiB0aGUgdGFyZ2V0IGFuZCB0cmFjayB3aGVyZSBpdCBlbmRzIHVwIGFmdGVyIHJvdGF0aW5nIGluIHlvdXIgaGVhZCwgcmF0aGVyIHRoYW4ganVkZ2luZyB0aGUgd2hvbGUgc2hhcGUncyBzaWxob3VldHRlIGF0IG9uY2U=', 'base64'), 'UTF8'), 'Practice with physical objects (rotate a real asymmetric object like a shoe or a hand) to build the underlying spatial-transformation skill', convert_from(decode('U2xvdyBkb3duIHNwZWNpZmljYWxseSBvbiBvcHRpb25zIHRoYXQgbG9vayAnYWxtb3N0IHJpZ2h0JyDigJQgdGhvc2UgYXJlIHVzdWFsbHkgdGhlIG1pcnJvcmVkIGRpc3RyYWN0b3Jz', 'base64'), 'UTF8')]::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'visuospatial-rotation'), 'overall', 31, 50, 'Average', 'Catches obvious mismatches but the closely-matched mirrored distractors still cause errors.', ARRAY['Practice specifically on mirror-vs-rotation discrimination — cover the target and try to redraw it rotated before looking at the options', 'Pick one asymmetric feature as your anchor and check it first on every option before considering the rest']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'visuospatial-rotation'), 'overall', 51, 70, 'Strong', 'Reliably identifies true rotations and rejects mirrored distractors on most trials.', ARRAY['Push your speed on easier trials — accuracy is already solid there', convert_from(decode('Tm90aWNlIHdoZXRoZXIgbGFyZ2VyIHJvdGF0aW9uIGFuZ2xlcyAoZnVydGhlciBmcm9tIHRoZSB0YXJnZXQncyBvcmlnaW5hbCBvcmllbnRhdGlvbikgc2xvdyB5b3UgZG93biBtb3JlIOKAlCB0aGF0J3MgYSBub3JtYWwsIHdlbGwtZG9jdW1lbnRlZCBwYXR0ZXJu', 'base64'), 'UTF8')]::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'visuospatial-rotation'), 'overall', 71, 85, 'Very Strong', 'Fast, accurate rotation-vs-mirror discrimination across nearly every trial, including the harder rotation angles.', ARRAY['This is a strong, genuine spatial-reasoning advantage — fields like engineering, design, and surgery lean on exactly this skill', convert_from(decode('Q29tcGFyZSB0aGlzIHJlc3VsdCB3aXRoIFNwYXRpYWwgSW50ZWxsaWdlbmNlJ3MgbWF0cml4LXJlYXNvbmluZyBzY29yZSDigJQgdGhleSBkcmF3IG9uIHJlbGF0ZWQgYnV0IGRpc3RpbmN0IHNwYXRpYWwgc2tpbGxz', 'base64'), 'UTF8')]::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'visuospatial-rotation'), 'overall', 86, 100, 'Exceptional', 'Near-perfect mental rotation performance across every trial and angle tested.', ARRAY['This is an elite spatial-rotation result — notice where it shows up as a real advantage in 3D-reasoning-heavy work', 'Consider fields that specifically reward strong 3D spatial reasoning under time pressure']::text[], NULL, 5);
